mapper.select:
select bo.organization_id, bo.parent_organization_id, bo.level, bo.tenant_id, bo.name, bo.sort,
bo.org_type,bo.status, DATE_FORMAT(bo.create_time, '%Y-%m-%d %H:%i:%s') as create_time
from b_organization bo
where bo.flag = 1


    and bo.tenant_id = #{param.tenantId}



    and bo.level = #{param.level}



    and bo.parent_organization_id = #{param.parentOrganizationId}




    and bo.name like #{name}


order by bo.sort asc

WITH RECURSIVE orgs AS (
SELECT bo.organization_id, bo.parent_organization_id, bo.level, bo.tenant_id, bo.name, bo.sort,
bo.org_type,bo.status, DATE_FORMAT(bo.create_time, '%Y-%m-%d %H:%i:%s') as create_time, bo.remark
FROM b_organization bo
WHERE bo.flag = 1


    and bo.tenant_id = #{param.tenantId}





        and bo.organization_id in (
        select s.organization_id from b_organization s where s.flag = 1 and bo.name like #{name}

            and s.tenant_id = #{param.tenantId}

        )




            and bo.organization_id in

                #{item}





UNION ALL

SELECT d.organization_id, d.parent_organization_id, d.level, d.tenant_id, d.name, d.sort,
d.org_type,d.status, DATE_FORMAT(d.create_time, '%Y-%m-%d %H:%i:%s') as create_time, d.remark
FROM b_organization d
JOIN orgs o ON d.parent_organization_id = o.organization_id
where d.flag = 1
)
SELECT * FROM orgs
